<script setup lang="ts">
const { data: goals, status, refresh } = await useFetch('/api/goals')
async function updateProgress(id: string, progress: number) { await $fetch(`/api/goals/${id}`, { method: 'PATCH', body: { progress } }); await refresh() }
</script>

<template><div class="app-container max-w-5xl"><PageHeader title="Мої цілі" description="Очікувані результати та особистий прогрес." icon="i-lucide-target" :count="goals?.length"/><div v-if="status==='pending'" class="space-y-2"><USkeleton v-for="i in 3" :key="i" class="h-28 rounded-xl"/></div><EmptyState v-else-if="!goals?.length" title="Цілей ще немає" description="Ваш PM додасть сюди командні або персональні цілі." icon="i-lucide-target"/><section v-else class="space-y-2"><article v-for="goal in goals" :key="goal.id" class="surface-card p-4"><div class="flex items-start justify-between gap-3"><div><h2 class="font-display">{{ goal.title }}</h2><p v-if="goal.description" class="mt-1 text-sm text-secondary">{{ goal.description }}</p><p v-if="goal.dueDate" class="mt-2 text-xs text-secondary"><UIcon name="i-lucide-calendar" class="mr-1 inline"/>До {{ goal.dueDate }}</p></div><strong class="text-[var(--color-accent)]">{{ goal.progress }}%</strong></div><input :value="goal.progress" type="range" min="0" max="100" step="10" class="mt-4 w-full accent-[var(--color-accent)]" @change="updateProgress(goal.id, Number(($event.target as HTMLInputElement).value))"/></article></section></div></template>
